package com.notifications.worker

import scala.concurrent.{Future, ExecutionContext}
import scala.concurrent.ExecutionContext.Implicits.global
import java.util.Properties
import javax.mail._
import javax.mail.internet._

// Domain models
case class NotificationJob(
  jobId: String,
  recipientEmail: String,
  subject: String,
  templateId: String,
  metadata: Map[String, String]
)

case class UserProfile(
  email: String,
  displayName: String,
  locale: String,
  replyToOverride: Option[String]
)

// Template resolution service
object TemplateService {
  private val templates = Map(
    "welcome" -> "Welcome to our platform, {name}!",
    "reset" -> "Password reset requested for {name}",
    "digest" -> "Weekly digest for {name}"
  )

  def resolve(templateId: String, vars: Map[String, String]): String = {
    templates.getOrElse(templateId, "Notification for {name}").foldLeft(_) {
      case (acc, _) => vars.foldLeft(acc) { case (s, (k, v)) => s.replace(s"{$k}", v) }
    }
  }

  def resolveBody(templateId: String, vars: Map[String, String]): String = {
    val base = s"Dear {name},\n\nThis is your $templateId notification."
    vars.foldLeft(base) { case (s, (k, v)) => s.replace(s"{$k}", v) }
  }
}

// Header sanitization utilities
object HeaderSanitizer {
  // RFC 5322 compliant header value sanitizer
  private val FOLDING_WHITESPACE = """\r\n[\t ]""".r
  private val BARE_NEWLINES = """[\r\n]""".r

  def sanitizeHeaderValue(value: String): String = {
    // First, collapse any folding whitespace (legitimate in RFC 5322)
    val unfolded = FOLDING_WHITESPACE.replaceAllIn(value, " ")
    // Then remove any remaining bare CR/LF characters
    BARE_NEWLINES.replaceAllIn(unfolded, "")
  }

  def sanitizeEmailAddress(email: String): String = {
    val cleaned = sanitizeHeaderValue(email)
    // Validate basic email structure
    if (cleaned.contains("@") && !cleaned.contains(" ")) cleaned
    else throw new IllegalArgumentException(s"Invalid email: $cleaned")
  }

  // Encode display name for use in From/Reply-To headers
  def encodeDisplayName(name: String): String = {
    val sanitized = sanitizeHeaderValue(name)
    if (sanitized.exists(c => c < 32 || c > 126 || c == '"' || c == '\\')) {
      MimeUtility.encodeWord(sanitized, "UTF-8", "Q")
    } else {
      s"\"$sanitized\""
    }
  }
}

// User profile resolution with caching
object UserProfileService {
  def fetchProfile(email: String): Future[UserProfile] = Future {
    // Simulated DB lookup - in production this queries user_profiles table
    UserProfile(
      email = email,
      displayName = email.split("@").head.capitalize,
