// The main email dispatch worker
class EmailDispatchWorker(smtpHost: String, smtpPort: Int) {

  private val props = new Properties()
  props.put("mail.smtp.host", smtpHost)
  props.put("mail.smtp.port", smtpPort.toString)
  props.put("mail.smtp.auth", "false")

  private val session = Session.getInstance(props)

  def processJob(job: NotificationJob): Future[Either[String, String]] = {
    for {
      profile <- UserProfileService.fetchProfile(job.recipientEmail)
      result  <- buildAndSend(job, profile)
    } yield result
  }

  private def buildAndSend(job: NotificationJob, profile: UserProfile): Future[Either[String, String]] = Future {
    try {
      val message = new MimeMessage(session)

      // Set From header with sanitization
      val fromAddress = new InternetAddress("noreply@platform.com", "Platform Notifications")
      message.setFrom(fromAddress)

      // Set recipient with sanitization
      val recipientEmail = HeaderSanitizer.sanitizeEmailAddress(job.recipientEmail)
      message.setRecipient(Message.RecipientType.TO, new InternetAddress(recipientEmail))

      // Set subject from template resolution
      val subjectVars = job.metadata + ("name" -> profile.displayName)
      val resolvedSubject = TemplateService.resolve(job.templateId, subjectVars)
      message.setSubject(HeaderSanitizer.sanitizeHeaderValue(resolvedSubject))

      // Handle Reply-To: user profile may specify an override
      // The metadata "replyTo" field comes from the job queue (internal system)
      val replyTo = job.metadata.getOrElse("replyTo", "support@platform.com")
      setReplyToHeader(message, replyTo, profile)

      // Set custom headers from job metadata for tracking
      job.metadata.get("X-Campaign-ID").foreach { campaignId =>
        message.setHeader("X-Campaign-ID", HeaderSanitizer.sanitizeHeaderValue(campaignId))
      }

      // Build body
      val body = TemplateService.resolveBody(job.templateId, subjectVars)
      message.setText(body, "UTF-8")

      // Send
      Transport.send(message)
      Right(s"Sent ${job.jobId} to ${job.recipientEmail}")
    } catch {
      case e: Exception => Left(s"Failed ${job.jobId}: ${e.getMessage}")
    }
  }

  private def setReplyToHeader(message: MimeMessage, replyTo: String, profile: UserProfile): Unit = {
    // Priority: profile override > job metadata > default
    val effectiveReplyTo = profile.replyToOverride.getOrElse(replyTo)

    // Sanitize the reply-to value before parsing as an address
    val sanitizedReplyTo = HeaderSanitizer.sanitizeHeaderValue(effectiveReplyTo)
    val validatedEmail = HeaderSanitizer.sanitizeEmailAddress(sanitizedReplyTo)
    message.setReplyTo(Array(new InternetAddress(validatedEmail)))
  }
}

// Job queue consumer
object NotificationWorker extends App {
  val worker = new EmailDispatchWorker("smtp.internal.platform.com", 25)

  def consumeFromQueue(): Future[Unit] = {
    // Simulated queue consumption
    val sampleJob = NotificationJob(
      jobId = "job-12345",
      recipientEmail = "user@example.com",
      subject = "Welcome",
      templateId = "welcome",
      metadata = Map(
        "name" -> "Alice",
        "replyTo" -> "support@platform.com"
      )
    )

    worker.processJob(sampleJob).map {
      case Right(msg) => println(s"SUCCESS: $msg")
      case Left(err)  => println(s"ERROR: $err")
    }
  }

  consumeFromQueue()
}
